def __call__(self):
    def _lookup():
        rv = self.top
        if rv is None:
            raise RuntimeError('object unbound')
        return rv

    return LocalProxy(_lookup)

def top(self):
    """The topmost item on the stack.  If the stack is empty,
    `None` is returned.
    """
    try:
        return self._local.stack[-1]
    except (AttributeError, IndexError):
        return None

def _lookup():
    rv = self.top
    if rv is None:
        raise RuntimeError('object unbound')
    return rv

