def data(self):
    if self._data is UNEVALUATED:
        if self._func_name is UNEVALUATED:
            raise ValueError('Cannot build the job data')

        if self._instance is UNEVALUATED:
            self._instance = None

        if self._args is UNEVALUATED:
            self._args = ()

        if self._kwargs is UNEVALUATED:
            self._kwargs = {}

        job_tuple = self._func_name, self._instance, self._args, self._kwargs
        self._data = self.serializer.dumps(job_tuple)
    return self._data

def to_dict(self, include_meta: bool = True, include_result: bool = True) -> dict:
    """Returns a serialization of the current job instance

    You can exclude serializing the `meta` dictionary by setting
    `include_meta=False`.

    Args:
        include_meta (bool, optional): Whether to include the Job's metadata. Defaults to True.
        include_result (bool, optional): Whether to include the Job's result. Defaults to True.

    Returns:
        dict: The Job serialized as a dictionary
    """
    obj = {
        'created_at': utcformat(self.created_at or utcnow()),
        'data': zlib.compress(self.data),
        'success_callback_name': self._success_callback_name if self._success_callback_name else '',
        'failure_callback_name': self._failure_callback_name if self._failure_callback_name else '',
        'stopped_callback_name': self._stopped_callback_name if self._stopped_callback_name else '',
        'started_at': utcformat(self.started_at) if self.started_at else '',
        'ended_at': utcformat(self.ended_at) if self.ended_at else '',
        'last_heartbeat': utcformat(self.last_heartbeat) if self.last_heartbeat else '',
        'worker_name': self.worker_name or '',
    }

    if self.retries_left is not None:
        obj['retries_left'] = self.retries_left
    if self.retry_intervals is not None:
        obj['retry_intervals'] = json.dumps(self.retry_intervals)
    if self.origin:
        obj['origin'] = self.origin
    if self.description is not None:
        obj['description'] = self.description
    if self.enqueued_at is not None:
        obj['enqueued_at'] = utcformat(self.enqueued_at)

    if self._result is not None and include_result:
        try:
            obj['result'] = self.serializer.dumps(self._result)
        except:  # noqa
            obj['result'] = "Unserializable return value"
    if self._exc_info is not None and include_result:
        obj['exc_info'] = zlib.compress(str(self._exc_info).encode('utf-8'))
    if self.timeout is not None:
        obj['timeout'] = self.timeout
    if self._success_callback_timeout is not None:
        obj['success_callback_timeout'] = self._success_callback_timeout
    if self._failure_callback_timeout is not None:
        obj['failure_callback_timeout'] = self._failure_callback_timeout
    if self._stopped_callback_timeout is not None:
        obj['stopped_callback_timeout'] = self._stopped_callback_timeout
    if self.result_ttl is not None:
        obj['result_ttl'] = self.result_ttl
    if self.failure_ttl is not None:
        obj['failure_ttl'] = self.failure_ttl
    if self._status is not None:
        obj['status'] = self._status
    if self._dependency_ids:
        obj['dependency_id'] = self._dependency_ids[0]  # for backwards compatibility
        obj['dependency_ids'] = json.dumps(self._dependency_ids)
    if self.meta and include_meta:
        obj['meta'] = self.serializer.dumps(self.meta)
    if self.ttl:
        obj['ttl'] = self.ttl

    if self.allow_dependency_failures is not None:
        # convert boolean to integer to avoid redis.exception.DataError
        obj["allow_dependency_failures"] = int(self.allow_dependency_failures)

    if self.enqueue_at_front is not None:
        obj["enqueue_at_front"] = int(self.enqueue_at_front)

    return obj

def get_current_job(self) -> Optional['Job']:
    """Returns the currently executing job instance.

    Returns:
        job (Job): The job instance.
    """
    job_id = self.get_current_job_id()
    if job_id is None:
        return None
    return self.job_class.fetch(job_id, self.connection, self.serializer)

def instance(self, value):
    self._instance = value
    self._data = UNEVALUATED

def args(self, value):
    self._args = value
    self._data = UNEVALUATED

def kwargs(self, value):
    self._kwargs = value
    self._data = UNEVALUATED

def __setattr__(self, name, value):
    ident = self.__ident_func__()
    storage = self.__storage__
    try:
        storage[ident][name] = value
    except KeyError:
        storage[ident] = {name: value}

def func_name(self, value):
    self._func_name = value
    self._data = UNEVALUATED

def started_job_registry(self):
    from .registry import StartedJobRegistry

    return StartedJobRegistry(
        self.origin, connection=self.connection, job_class=self.__class__, serializer=self.serializer
    )

def exc_info(self) -> Optional[str]:
    """
    Get the latest result and returns `exc_info` only if the latest result is a failure.
    """
    warnings.warn("job.exc_info is deprecated, use job.latest_result() instead.", DeprecationWarning)

    from .results import Result

    if self.supports_redis_streams:
        if not self._cached_result:
            self._cached_result = self.latest_result()

        if self._cached_result and self._cached_result.type == Result.Type.FAILED:
            return self._cached_result.exc_string

    return self._exc_info

def supports_redis_streams(self) -> bool:
    """Only supported by Redis server >= 5.0 is required."""
    return self.get_redis_server_version() >= (5, 0, 0)

def restore(self, raw_data) -> Any:
    """Overwrite properties with the provided values stored in Redis.

    Args:
        raw_data (_type_): The raw data to load the job data from

    Raises:
        NoSuchJobError: If there way an error getting the job data
    """
    obj = decode_redis_hash(raw_data)
    try:
        raw_data = obj['data']
    except KeyError:
        raise NoSuchJobError('Unexpected job format: {0}'.format(obj))

    try:
        self.data = zlib.decompress(raw_data)
    except zlib.error:
        # Fallback to uncompressed string
        self.data = raw_data

    self.created_at = str_to_date(obj.get('created_at'))
    self.origin = as_text(obj.get('origin')) if obj.get('origin') else ''
    self.worker_name = obj.get('worker_name').decode() if obj.get('worker_name') else None
    self.description = as_text(obj.get('description')) if obj.get('description') else None
    self.enqueued_at = str_to_date(obj.get('enqueued_at'))
    self.started_at = str_to_date(obj.get('started_at'))
    self.ended_at = str_to_date(obj.get('ended_at'))
    self.last_heartbeat = str_to_date(obj.get('last_heartbeat'))
    result = obj.get('result')
    if result:
        try:
            self._result = self.serializer.loads(result)
        except Exception:
            self._result = UNSERIALIZABLE_RETURN_VALUE_PAYLOAD
    self.timeout = parse_timeout(obj.get('timeout')) if obj.get('timeout') else None
    self.result_ttl = int(obj.get('result_ttl')) if obj.get('result_ttl') else None
    self.failure_ttl = int(obj.get('failure_ttl')) if obj.get('failure_ttl') else None
    self._status = obj.get('status').decode() if obj.get('status') else None

    if obj.get('success_callback_name'):
        self._success_callback_name = obj.get('success_callback_name').decode()

    if 'success_callback_timeout' in obj:
        self._success_callback_timeout = int(obj.get('success_callback_timeout'))

    if obj.get('failure_callback_name'):
        self._failure_callback_name = obj.get('failure_callback_name').decode()

    if 'failure_callback_timeout' in obj:
        self._failure_callback_timeout = int(obj.get('failure_callback_timeout'))

    if obj.get('stopped_callback_name'):
        self._stopped_callback_name = obj.get('stopped_callback_name').decode()

    if 'stopped_callback_timeout' in obj:
        self._stopped_callback_timeout = int(obj.get('stopped_callback_timeout'))

    dep_ids = obj.get('dependency_ids')
    dep_id = obj.get('dependency_id')  # for backwards compatibility
    self._dependency_ids = json.loads(dep_ids.decode()) if dep_ids else [dep_id.decode()] if dep_id else []
    allow_failures = obj.get('allow_dependency_failures')
    self.allow_dependency_failures = bool(int(allow_failures)) if allow_failures else None
    self.enqueue_at_front = bool(int(obj['enqueue_at_front'])) if 'enqueue_at_front' in obj else None
    self.ttl = int(obj.get('ttl')) if obj.get('ttl') else None
    try:
        self.meta = self.serializer.loads(obj.get('meta')) if obj.get('meta') else {}
    except Exception:  # depends on the serializer
        self.meta = {'unserialized': obj.get('meta', {})}

    self.retries_left = int(obj.get('retries_left')) if obj.get('retries_left') else None
    if obj.get('retry_intervals'):
        self.retry_intervals = json.loads(obj.get('retry_intervals').decode())

    raw_exc_info = obj.get('exc_info')
    if raw_exc_info:
        try:
            self._exc_info = as_text(zlib.decompress(raw_exc_info))
        except zlib.error:
            # Fallback to uncompressed string
            self._exc_info = as_text(raw_exc_info)

def as_text(v: Union[bytes, str]) -> str:
    """Converts a bytes value to a string using `utf-8`.

    Args:
        v (Union[bytes, str]): The value (bytes or string)

    Raises:
        ValueError: If the value is not bytes or string

    Returns:
        value (Optional[str]): Either the decoded string or None
    """
    if isinstance(v, bytes):
        return v.decode('utf-8')
    elif isinstance(v, str):
        return v
    else:
        raise ValueError('Unknown type %r' % type(v))

def utcparse(string: str) -> dt.datetime:
    try:
        return datetime.datetime.strptime(string, _TIMESTAMP_FORMAT)
    except ValueError:
        # This catches any jobs remain with old datetime format
        return datetime.datetime.strptime(string, '%Y-%m-%dT%H:%M:%SZ')

def str_to_date(date_str: Optional[str]) -> Union[dt.datetime, Any]:
    if not date_str:
        return
    else:
        return utcparse(date_str.decode())

def shutdown_requested_date(self):
    """Fetches shutdown_requested_date from Redis."""
    shutdown_requested_timestamp = self.connection.hget(self.key, 'shutdown_requested_date')
    if shutdown_requested_timestamp is not None:
        return utcparse(as_text(shutdown_requested_timestamp))

def death_date(self):
    """Fetches death date from Redis."""
    death_timestamp = self.connection.hget(self.key, 'death')
    if death_timestamp is not None:
        return utcparse(as_text(death_timestamp))

def __init__(self, timeout, exception=BaseTimeoutException, **kwargs):
    self._timeout = timeout
    self._exception = exception

def __init__(self, func: Union[str, Callable[..., Any]], timeout: Optional[Any] = None):
    if not isinstance(func, str) and not inspect.isfunction(func) and not inspect.isbuiltin(func):
        raise ValueError('Callback `func` must be a string or function')

    self.func = func
    self.timeout = parse_timeout(timeout) if timeout else CALLBACK_TIMEOUT

def parse_timeout(timeout: Union[int, float, str]) -> int:
    """Transfer all kinds of timeout format to an integer representing seconds"""
    if not isinstance(timeout, numbers.Integral) and timeout is not None:
        try:
            timeout = int(timeout)
        except ValueError:
            digit, unit = timeout[:-1], (timeout[-1:]).lower()
            unit_second = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
            try:
                timeout = int(digit) * unit_second[unit]
            except (ValueError, KeyError):
                raise TimeoutFormatError(
                    'Timeout must be an integer or a string representing an integer, or '
                    'a string with format: digits + unit, unit can be "d", "h", "m", "s", '
                    'such as "1h", "23m".'
                )

    return timeout

def parse_schedule(schedule_in, schedule_at):
    if schedule_in is not None:
        if schedule_at is not None:
            raise click.BadArgumentUsage('You can\'t specify both --schedule-in and --schedule-at')
        return datetime.now(timezone.utc) + timedelta(seconds=parse_timeout(schedule_in))
    elif schedule_at is not None:
        return datetime.strptime(schedule_at, '%Y-%m-%dT%H:%M:%S')

def unregister(worker: 'Worker', pipeline: Optional['Pipeline'] = None):
    """Remove Worker key from Redis

    Args:
        worker (Worker): The Worker
        pipeline (Optional[Pipeline], optional): Redis Pipeline. Defaults to None.
    """
    if pipeline is None:
        connection = worker.connection.pipeline()
    else:
        connection = pipeline

    connection.srem(worker.redis_workers_keys, worker.key)
    for name in worker.queue_names():
        redis_key = WORKERS_BY_QUEUE_KEY % name
        connection.srem(redis_key, worker.key)

    if pipeline is None:
        connection.execute()

def clean_worker_registry(queue: 'Queue'):
    """Delete invalid worker keys in registry.

    Args:
        queue (Queue): The Queue
    """
    keys = list(get_keys(queue))

    with queue.connection.pipeline() as pipeline:
        for key in keys:
            pipeline.exists(key)
        results = pipeline.execute()

        invalid_keys = []

        for i, key_exists in enumerate(results):
            if not key_exists:
                invalid_keys.append(keys[i])

        if invalid_keys:
            for invalid_subset in split_list(invalid_keys, MAX_KEYS):
                pipeline.srem(WORKERS_BY_QUEUE_KEY % queue.name, *invalid_subset)
                pipeline.srem(REDIS_WORKER_KEYS, *invalid_subset)
                pipeline.execute()

def pop(self):
    """Removes the topmost item from the stack, will return the
    old value or `None` if the stack was already empty.
    """
    stack = getattr(self._local, 'stack', None)
    if stack is None:
        return None
    elif len(stack) == 1:
        release_local(self._local)
        return stack[-1]
    else:
        return stack.pop()

def cleanup(self):
    """Manually clean up the data in the locals for this context.  Call
    this at the end of the request or use `make_middleware()`.
    """
    for local in self.locals:
        release_local(local)

def pop_exc_handler(self):
    """Pops the latest exception handler off of the exc handler stack."""
    return self._exc_handlers.pop()

def __init__(self):
    object.__setattr__(self, '__storage__', {})
    object.__setattr__(self, '__ident_func__', get_ident)

def __init__(self, local, name=None):
    object.__setattr__(self, '_LocalProxy__local', local)
    object.__setattr__(self, '__name__', name)

def __init__(self, exclude=None, *args, **kwargs):
    self.exclude = exclude
    super().__init__(*args, **kwargs)

def __call__(self, proxy):
    """Create a proxy for a name."""
    return LocalProxy(self, proxy)

def push_exc_handler(self, handler_func):
    """Pushes an exception handler onto the exc handler stack."""
    self._exc_handlers.append(handler_func)

def _get_current_object(self):
    """Return the current object.  This is useful if you want the real
    object behind the proxy at a time for performance reasons or because
    you want to pass the object into a different context.
    """
    if not hasattr(self.__local, '__release_local__'):
        return self.__local()
    try:
        return getattr(self.__local, self.__name__)
    except AttributeError:
        raise RuntimeError('no object bound to %s' % self.__name__)

def __dict__(self):
    try:
        return self._get_current_object().__dict__
    except RuntimeError:
        raise AttributeError('__dict__')

def __repr__(self):
    try:
        obj = self._get_current_object()
    except RuntimeError:
        return '<%s unbound>' % self.__class__.__name__
    return repr(obj)

def __dir__(self):
    try:
        return dir(self._get_current_object())
    except RuntimeError:
        return []

def __getattr__(self, name):
    if name == '__members__':
        return dir(self._get_current_object())
    return getattr(self._get_current_object(), name)

def __len__(self):
    """Returns the number of jobs in this registry"""
    return self.count

def current_timestamp() -> int:
    """Returns current UTC timestamp

    Returns:
        int: _description_
    """
    return calendar.timegm(datetime.datetime.utcnow().utctimetuple())

def requeue(cli_config, queue, all, job_class, serializer, job_ids, **options):
    """Requeue failed jobs."""

    failed_job_registry = FailedJobRegistry(
        queue, connection=cli_config.connection, job_class=job_class, serializer=serializer
    )
    if all:
        job_ids = failed_job_registry.get_job_ids()

    if not job_ids:
        click.echo('Nothing to do')
        sys.exit(0)

    click.echo('Requeueing {0} jobs from failed queue'.format(len(job_ids)))
    fail_count = 0
    with click.progressbar(job_ids) as job_ids:
        for job_id in job_ids:
            try:
                failed_job_registry.requeue(job_id)
            except InvalidJobOperationError:
                fail_count += 1

    if fail_count > 0:
        click.secho('Unable to requeue {0} jobs from failed job registry'.format(fail_count), fg='red')

def connection(self):
    if self._connection:
        return self._connection
    self._connection = self._connection_class(
        connection_pool=ConnectionPool(connection_class=self._pool_class, **self._pool_kwargs)
    )
    return self._connection

def prepare_registries(self, queue_names: str = None):
    """Prepare scheduled job registries for use"""
    self._scheduled_job_registries = []
    if not queue_names:
        queue_names = self._acquired_locks
    for name in queue_names:
        self._scheduled_job_registries.append(
            ScheduledJobRegistry(name, connection=self.connection, serializer=self.serializer)
        )

def handle_exception(self, job: 'Job', *exc_info):
    """Walks the exception handler stack to delegate exception handling.
    If the job cannot be deserialized, it will raise when func_name or
    the other properties are accessed, which will stop exceptions from
    being properly logged, so we guard against it here.
    """
    self.log.debug('Handling exception for %s.', job.id)
    exc_string = ''.join(traceback.format_exception(*exc_info))
    try:
        extra = {
            'func': job.func_name,
            'arguments': job.args,
            'kwargs': job.kwargs,
        }
        func_name = job.func_name
    except DeserializationError:
        extra = {}
        func_name = '<DeserializationError>'

    # the properties below should be safe however
    extra.update({'queue': job.origin, 'job_id': job.id})

    # func_name
    self.log.error(
        '[Job %s]: exception raised while executing (%s)\n%s', job.id, func_name, exc_string, extra=extra
    )

    for handler in self._exc_handlers:
        self.log.debug('Invoking exception handler %s', handler)
        fallthrough = handler(job, *exc_info)

        # Only handlers with explicit return values should disable further
        # exc handling, so interpret a None return value as True.
        if fallthrough is None:
            fallthrough = True

        if not fallthrough:
            break

def parse_function_args(arguments):
    args = []
    kwargs = {}

    for argument in arguments:
        keyword, value = parse_function_arg(argument, len(args) + 1)
        if keyword is not None:
            if keyword in kwargs:
                raise click.BadParameter('You can\'t specify multiple values for the same keyword.')
            kwargs[keyword] = value
        else:
            args.append(value)
    return args, kwargs

def colorize(self, color_key, text):
    if self.notty:
        return text
    else:
        return self.codes[color_key] + text + self.codes["reset"]

def is_tty(self):
    isatty = getattr(self.stream, 'isatty', None)
    return isatty and isatty()

def should_reacquire_locks(self):
    """Returns True if lock_acquisition_time is longer than 10 minutes ago"""
    if self._queue_names == self.acquired_locks:
        return False
    if not self.lock_acquisition_time:
        return True
    return (datetime.now() - self.lock_acquisition_time).total_seconds() > DEFAULT_SCHEDULER_FALLBACK_PERIOD

def get_locking_key(cls, name: str):
    """Returns scheduler key for a given queue name"""
    return SCHEDULER_LOCKING_KEY_TEMPLATE % name

def heartbeat(self):
    """Updates the TTL on scheduler keys and the locks"""
    self.log.debug('Scheduler sending heartbeat to %s', ', '.join(self.acquired_locks))
    if len(self._acquired_locks) > 1:
        with self.connection.pipeline() as pipeline:
            for name in self._acquired_locks:
                key = self.get_locking_key(name)
                pipeline.expire(key, self.interval + 60)
            pipeline.execute()
    elif self._acquired_locks:
        key = self.get_locking_key(next(iter(self._acquired_locks)))
        self.connection.expire(key, self.interval + 60)

def work(self):
    self._install_signal_handlers()

    while True:
        if self._stop_requested:
            self.stop()
            break

        if self.should_reacquire_locks:
            self.acquire_locks()

        self.enqueue_scheduled_jobs()
        self.heartbeat()
        time.sleep(self.interval)

def _get_state(self):
    """Raise a DeprecationWarning if ``worker.state == X`` is used"""
    warnings.warn("worker.state is deprecated, use worker.get_state() instead.", DeprecationWarning)
    return self.get_state()

def signal_name(signum):
    try:
        if sys.version_info[:2] >= (3, 5):
            return signal.Signals(signum).name
        else:
            return _signames[signum]

    except KeyError:
        return 'SIG_UNKNOWN'
    except ValueError:
        return 'SIG_UNKNOWN'

def request_stop_sigrtmin(self, signum, frame):
    if self.imminent_shutdown_delay == 0:
        self.log.warning('Imminent shutdown, raising ShutDownImminentException immediately')
        self.request_force_stop_sigrtmin(signum, frame)
    else:
        self.log.warning(
            'Imminent shutdown, raising ShutDownImminentException in %d seconds', self.imminent_shutdown_delay
        )
        signal.signal(signal.SIGRTMIN, self.request_force_stop_sigrtmin)
        signal.signal(signal.SIGALRM, self.request_force_stop_sigrtmin)
        signal.alarm(self.imminent_shutdown_delay)

def should_run_maintenance_tasks(self):
    """Maintenance tasks should run on first startup or every 10 minutes."""
    if self.last_cleaned_at is None:
        return True
    if (utcnow() - self.last_cleaned_at) > timedelta(seconds=self.maintenance_interval):
        return True
    return False

def key(self):
    """Returns the worker's Redis hash key."""
    return self.redis_worker_namespace_prefix + self.name

def pubsub_channel_name(self):
    """Returns the worker's Redis hash key."""
    return PUBSUB_CHANNEL_TEMPLATE % self.name

def is_horse(self):
    """Returns whether or not this is the worker or the work horse."""
    return self._is_horse

def teardown(self):
    if not self.is_horse:
        if self.scheduler:
            self.stop_scheduler()
        self.register_death()
        self.unsubscribe()

def set_shutdown_requested_date(self):
    """Sets the date on which the worker received a (warm) shutdown request"""
    self.connection.hset(self.key, 'shutdown_requested_date', utcformat(self._shutdown_requested_date))

def _shutdown(self):
    """
    If shutdown is requested in the middle of a job, wait until
    finish before shutting down and save the request in redis
    """
    if self.get_state() == WorkerStatus.BUSY:
        self._stop_requested = True
        self.set_shutdown_requested_date()
        self.log.debug('Stopping after current horse is finished. Press Ctrl+C again for a cold shutdown.')
        if self.scheduler:
            self.stop_scheduler()
    else:
        if self.scheduler:
            self.stop_scheduler()
        raise StopRequested()

def stop_scheduler(self):
    """Ensure scheduler process is stopped
    Will send the kill signal to scheduler process,
    if there's an OSError, just passes and `join()`'s the scheduler process,
    waiting for the process to finish.
    """
    if self.scheduler._process and self.scheduler._process.pid:
        try:
            os.kill(self.scheduler._process.pid, signal.SIGTERM)
        except OSError:
            pass
        self.scheduler._process.join()

def reorder_queues(self, reference_queue: 'Queue'):
    """Reorder the queues according to the strategy.
    As this can be defined both in the `Worker` initialization or in the `work` method,
    it doesn't take the strategy directly, but rather uses the private `_dequeue_strategy` attribute.

    Args:
        reference_queue (Union[Queue, str]): The queues to reorder
    """
    if self._dequeue_strategy is None:
        self._dequeue_strategy = DequeueStrategy.DEFAULT

    if self._dequeue_strategy not in ("default", "random", "round_robin"):
        raise ValueError(
            f"Dequeue strategy {self._dequeue_strategy} is not allowed. Use `default`, `random` or `round_robin`."
        )
    if self._dequeue_strategy == DequeueStrategy.DEFAULT:
        return
    if self._dequeue_strategy == DequeueStrategy.ROUND_ROBIN:
        pos = self._ordered_queues.index(reference_queue)
        self._ordered_queues = self._ordered_queues[pos + 1 :] + self._ordered_queues[: pos + 1]
        return
    if self._dequeue_strategy == DequeueStrategy.RANDOM:
        shuffle(self._ordered_queues)
        return

def reorder_queues(self, reference_queue):
    pos = self._ordered_queues.index(reference_queue)
    self._ordered_queues = self._ordered_queues[pos + 1 :] + self._ordered_queues[: pos + 1]

def handle_work_horse_killed(self, job, retpid, ret_val, rusage):
    if self._work_horse_killed_handler is None:
        return

    self._work_horse_killed_handler(job, retpid, ret_val, rusage)

def new_timer(self):
    """Returns a new timer since timers can only be used once."""
    return threading.Timer(self._timeout, self.handle_death_penalty)

def handle_death_penalty(self):
    """Raises an asynchronous exception in another thread.

    Reference http://docs.python.org/c-api/init.html#PyThreadState_SetAsyncExc for more info.
    """
    ret = ctypes.pythonapi.PyThreadState_SetAsyncExc(
        ctypes.c_long(self._target_thread_id), ctypes.py_object(self._exception)
    )
    if ret == 0:
        raise ValueError("Invalid thread ID {}".format(self._target_thread_id))
    elif ret > 1:
        ctypes.pythonapi.PyThreadState_SetAsyncExc(ctypes.c_long(self._target_thread_id), 0)
        raise SystemError("PyThreadState_SetAsyncExc failed")

def setup_death_penalty(self):
    """Starts the timer."""
    if self._timeout <= 0:
        return
    self._timer = self.new_timer()
    self._timer.start()

